<?php
declare(strict_types=1); require_once __DIR__.DIRECTORY_SEPARATOR.'auth.php'; admin_require_login(); send_security_headers(true); header('Content-Type: text/html; charset=utf-8'); $p=db_connection();$msg=''; if($_SERVER['REQUEST_METHOD']==='POST'){admin_csrf_check();$id=filter_var($_POST['photo_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$action=$_POST['action']??'';if(!$id||!in_array($action,['approve','hide'],true)){http_response_code(400);exit('Invalid photo action.');}if($action==='approve'){if(!admin_public_consent($p,$id))$msg='This photo has no valid public-display consent and cannot be approved.';else{$q=$p->prepare("UPDATE photos SET status='active',approval_status='approved' WHERE id=?");$q->execute([$id]);$msg='Photo approved.';}}else{$q=$p->prepare("UPDATE photos SET status='hidden',approval_status='rejected' WHERE id=?");$q->execute([$id]);$msg='Photo hidden / rejected.';}}
$vid=filter_var($_GET['visitor']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:0;$sql='SELECT ph.id,ph.original_filename,ph.uploaded_at,ph.status,ph.approval_status,v.name visitor_name,c.consent_version FROM photos ph JOIN visitors v ON v.id=ph.visitor_id LEFT JOIN consents c ON c.id=ph.consent_id AND c.visitor_id=ph.visitor_id'.($vid?' WHERE ph.visitor_id=:vid':'').' ORDER BY ph.id DESC LIMIT 200';$q=$p->prepare($sql);if($vid)$q->bindValue(':vid',$vid,PDO::PARAM_INT);$q->execute();$rows=$q->fetchAll();echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Photo review</title></head><body><h1>Photo review</h1><p><a href="index.php">Dashboard</a> | <a href="visitors.php">Visitors</a></p>';if($msg!=='')echo '<p role="status">'.admin_e($msg).'</p>';echo '<p>Latest 200 photos'.($vid?' for selected visitor':'').'.</p><table border="1"><tr><th>Preview</th><th>Visitor</th><th>Original filename</th><th>Uploaded</th><th>Consent</th><th>Status</th><th>Actions</th></tr>';foreach($rows as $x){$valid=(string)$x['consent_version']===SLIDESHOW_PUBLIC_CONSENT_VERSION;echo '<tr><td><img src="photo.php?id='.(int)$x['id'].'" alt="Private photo preview" width="120"></td><td>'.admin_e($x['visitor_name']).'</td><td>'.admin_e($x['original_filename']).'</td><td>'.admin_e($x['uploaded_at']).'</td><td>'.($valid?'Valid public consent':'No valid public consent').'</td><td>'.admin_e($x['approval_status']).' / '.admin_e($x['status']).'</td><td><form method="post"><input type="hidden" name="csrf_token" value="'.admin_e(csrf_token()).'"><input type="hidden" name="photo_id" value="'.(int)$x['id'].'"><button name="action" value="approve"'.(!$valid?' disabled':'').'>Approve</button> <button name="action" value="hide">Hide / reject</button></form></td></tr>';}if(!$rows)echo '<tr><td colspan="7">No photos found.</td></tr>';echo '</table></body></html>';
